The docstring fully determines the output. The merge of two sorted lists, with repetitions kept, is exactly `sorted(a + b)`. So `post` builds that list on its own and compares it with `result` element by element. `pre` checks the stated input domain: length, value range and non-decreasing order.

```python
def _is_sorted(xs):
    for k in range(len(xs) - 1):
        if xs[k] > xs[k + 1]:
            return False
    return True


def _valid_list(xs):
    if len(xs) > 4:
        return False
    for x in xs:
        if x < -9 or x > 9:
            return False
    return _is_sorted(xs)


def pre(a, b):
    return _valid_list(a) and _valid_list(b)


def post(a, b, result):
    combined = []
    for x in a:
        combined.append(x)
    for y in b:
        combined.append(y)
    expected = sorted(combined)
    if len(result) != len(expected):
        return False
    for k in range(len(expected)):
        if result[k] != expected[k]:
            return False
    return True
```
